import test from'node:test';import assert from'node:assert/strict';import{decoder}from'tetris-fumen';import{createWasmSolver}from'../src/wasm-backend.mjs';import{calculateSaves,calculateMinimalsFeature}from'../src/features.mjs';
const B='v115@9gglIeglHewwhlzhBexwzhEewwJeAgH',P='T,[^TIL]!,*p2';
test('ezsaves T 1008/1008 with dual queue contract',async()=>{const s=await createWasmSolver(4);try{const r=calculateSaves({sourceFumen:B,pattern:P,wantedSave:'T',solver:s});assert.equal(r.pathPattern,'T,[JSZO]!,*p2');assert.equal(r.analysisPattern,P);assert.deepEqual([r.success,r.total],[1008,1008]);assert.equal(r.failedQueues.length,0)}finally{s.close()}});
test('ezminimals T keeps exact cardinality and coverage while representative geometry may differ',async()=>{const s=await createWasmSolver(4);try{const r=calculateMinimalsFeature({sourceFumen:B,pattern:P,wantedSave:'T',solver:s});assert.equal(r.minimalCount,7);assert.deepEqual([...r.coverageCounts].sort((a,b)=>b-a),[288,288,288,288,288,192,144]);const pages=decoder.decode(r.fumen);assert.equal(pages.length,7);assert.deepEqual(pages.map(p=>p.comment).sort(),['14.29% (144/1008)','19.05% (192/1008)',...Array(5).fill('28.57% (288/1008)')].sort())}finally{s.close()}});
